     background-color: #eff6ff;
     border-color: #93c5fd;
 }

 .checkbox-option label {
     cursor: pointer;
     flex: 1;
     font-weight: 500;
     padding: 0.75rem 0.75rem 0.75rem 0; /* Left padding is 0 because input has margin */
 }

