 const { chromium } = require('playwright');
 const fs = require('fs');
 const path = require('path');

 (async () => {
   const browser = await chromium.launch();
   const page = await browser.newPage();

   // Use absolute path for file:// URL
   const filePath = 'file://' + path.resolve('index.html');
   await page.goto(filePath, { waitUntil: 'networkidle' });

   // Inject axe-core
   await page.addScriptTag({ path: '/tmp/axe.min.js' });

   // Run axe
   const results = await page.evaluate(async () => {
     return await window.axe.run();
   });

   const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
   const bp = results.violations.filter(v => v.tags.includes('best-practice'));

   console.log(JSON.stringify({
     wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, nodes: v.nodes.length })),
     bp: bp.map(v => ({ id: v.id, description: v.description, nodes: v.nodes.length }))
   }, null, 2));

   await browser.close();
   process.exit(wcag.length > 0 ? 1 : 0);
 })();

